CREATE DATABASE vaclab;
\c vaclab
CREATE TABLE orders (
    order_id    integer PRIMARY KEY,
    customer_id integer NOT NULL,
    status      text    NOT NULL,
    amount      numeric(10,2) NOT NULL
) WITH (autovacuum_enabled = false);
INSERT INTO orders
SELECT g, (g % 5000) + 1, 'NEW', (g % 900) + 100
  FROM generate_series(1, 100000) AS g;

ANALYZE orders;
SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size,
       relpages, reltuples
  FROM pg_class WHERE relname = 'orders';

SELECT n_live_tup, n_dead_tup, last_vacuum, last_autovacuum
  FROM pg_stat_user_tables WHERE relname = 'orders';
SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size;

SELECT n_live_tup, n_dead_tup, last_vacuum, vacuum_count
  FROM pg_stat_user_tables WHERE relname = 'orders';
SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size;

INSERT INTO orders
SELECT g, (g % 5000) + 1, 'NEW', (g % 900) + 100
  FROM generate_series(100001, 130000) AS g;
SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size;

DELETE FROM orders WHERE status = 'SHIPPED';
VACUUM (VERBOSE) orders;
SELECT pg_size_pretty(pg_relation_size('orders')) AS table_size;

# before
#log_autovacuum_min_duration = 10min	# log autovacuum activity;

# after
log_autovacuum_min_duration = 0	# log autovacuum activity;

SELECT n_dead_tup, last_autovacuum, autovacuum_count,
       last_autoanalyze, autoanalyze_count, total_autovacuum_time
  FROM pg_stat_user_tables WHERE relname = 'orders';

ALTER TABLE orders SET (autovacuum_enabled = false);
UPDATE orders SET amount = amount + 1;
SET vacuum_cost_delay = '50ms';
SET vacuum_cost_limit = 20;
SET track_cost_delay_timing = on;
\timing on
VACUUM orders;

SELECT pid, relid::regclass AS table_name, phase,
       heap_blks_total, heap_blks_scanned, heap_blks_vacuumed,
       index_vacuum_count, round(delay_time) AS delay_ms
  FROM pg_stat_progress_vacuum;

SELECT pid, wait_event_type, wait_event, state, query
  FROM pg_stat_activity WHERE query LIKE 'VACUUM%';

UPDATE orders SET amount = amount + 1;
SHOW vacuum_cost_delay;
\timing on
VACUUM orders;

ALTER TABLE orders RESET (autovacuum_enabled);
ALTER TABLE orders SET (autovacuum_vacuum_scale_factor = 0.01,
                        autovacuum_vacuum_threshold = 1000);
SELECT relname, reloptions FROM pg_class WHERE relname = 'orders';

#log_autovacuum_min_duration = 10min	# log autovacuum activity;
#autovacuum_max_workers = 3		# max number of autovacuum subprocesses
#autovacuum_vacuum_cost_limit = -1	# default vacuum cost limit for

SELECT pg_reload_conf();
\c postgres
DROP DATABASE vaclab;

# Open psql as the postgres user on db1
sudo -u postgres psql vaclab

# Vacuum one table and print a detailed report (in psql)
VACUUM (VERBOSE) orders;

# Vacuum and analyze one table from the shell
sudo -u postgres vacuumdb --analyze --verbose --table=orders vaclab

# Vacuum and analyze every database, 2 jobs in parallel
sudo -u postgres vacuumdb --all --analyze --jobs=2

# Dead tuples and last (auto)vacuum per table (in psql)
SELECT relname, n_live_tup, n_dead_tup, last_vacuum, last_autovacuum, autovacuum_count FROM pg_stat_user_tables ORDER BY n_dead_tup DESC;

# All autovacuum settings and whether they need reload (sighup) or restart (postmaster)
SELECT name, setting, unit, context FROM pg_settings WHERE name LIKE 'autovacuum%' ORDER BY name;

# Running VACUUMs and their phase
SELECT pid, relid::regclass, phase, heap_blks_total, heap_blks_scanned, round(delay_time) FROM pg_stat_progress_vacuum;

# Edit server-wide settings, then reload (no restart needed for autovacuum_max_workers in PostgreSQL 18)
sudo nano /etc/postgresql/18/main/postgresql.conf
sudo systemctl reload postgresql@18-main

# Read autovacuum entries in the server log (needs log_autovacuum_min_duration other than -1)
sudo grep -A13 'automatic vacuum' /var/log/postgresql/postgresql-18-main.log

# Per-table autovacuum settings: set, check, undo (in psql)
ALTER TABLE orders SET (autovacuum_vacuum_scale_factor = 0.01, autovacuum_vacuum_threshold = 1000);
SELECT relname, reloptions FROM pg_class WHERE relname = 'orders';
ALTER TABLE orders RESET (autovacuum_vacuum_scale_factor, autovacuum_vacuum_threshold);

